const raw = $input.first().json;
const payload = raw.body || raw;
const isEmptyPayload = !payload || Object.keys(payload).length === 0;

// Manual test runs have no payload - default to a sample keyword so the workflow is testable end to end
const triggerKeyword = payload.keyword || (isEmptyPayload ? 'best crm software' : null);

return [{
  json: {
    triggerKeyword: triggerKeyword || null,
    results: [],
    processedCount: 0
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    queue: [{ keyword: item.triggerKeyword }]
  }
}];

const state = $('If Ad Hoc Keyword Exists').first().json;
const response = $input.first().json;
const keywords = response.keywords || response.items || (Array.isArray(response) ? response : []);

const queue = keywords.map(k => ({
  keyword: k.keyword || k.query || String(k)
}));

return [{
  json: {
    ...state,
    queue
  }
}];

const item = $input.first().json;
const queue = [...(item.queue || [])];
const next = queue.shift();

return [{
  json: {
    ...item,
    queue,
    currentKeyword: next ? next.keyword : null,
    hasNext: !!next
  }
}];

const state = $('Retrieve Next Keyword from Queue').first().json;
const response = $input.first().json;

const rawResults = response.organic_results || response.results || response.items || [];
const results = rawResults.slice(0, 20).map((r, idx) => {
  const url = r.link || r.url || '';
  let domain = r.domain || '';
  if (!domain) {
    try { domain = new URL(url).host; } catch (e) { domain = ''; }
  }
  return { position: Number(r.position) || (idx + 1), domain, url, title: r.title || '' };
});

const serpFeatures = {
  hasFeaturedSnippet: !!(response.answer_box || response.featured_snippet),
  hasPeopleAlsoAsk: !!(response.related_questions || response.people_also_ask),
  hasShoppingResults: !!response.shopping_results,
  hasVideoResults: !!(response.video_results || response.inline_videos),
  hasLocalPack: !!response.local_results
};

return [{
  json: {
    ...state,
    snapshotTakenAt: new Date().toISOString(),
    currentResults: results,
    currentSerpFeatures: serpFeatures
  }
}];

const state = $('Normalize SERP Snapshot Data').first().json;
const response = $input.first().json;

const rawSeries = response.snapshots || response.items || (Array.isArray(response) ? response : []);

let timeline = rawSeries.map(s => ({
  date: s.snapshotTakenAt || s.date || s.createdAt || null,
  results: (s.results || []).map(r => ({ position: r.position, domain: r.domain, url: r.url, title: r.title })),
  serpFeatures: s.serpFeatures || {}
})).filter(p => p.date);

// Make sure today's freshly captured snapshot is represented even if the DB hasn't indexed it yet
const hasToday = timeline.some(p => p.date === state.snapshotTakenAt);
if (!hasToday) {
  timeline.push({ date: state.snapshotTakenAt, results: state.currentResults, serpFeatures: state.currentSerpFeatures });
}

timeline.sort((a, b) => new Date(a.date) - new Date(b.date));
timeline = timeline.slice(-state.historicalWindowSize);

return [{
  json: {
    ...state,
    timeline,
    timelineLength: timeline.length,
    hasEnoughHistory: timeline.length >= state.minPeriodsForDrift
  }
}];

const state = $input.first().json;

const INFO_HINTS = /\b(blog|wiki|guide|tutorial|what is|how to|definition|learn)\b/i;
const COMMERCIAL_HINTS = /\b(buy|shop|price|pricing|deal|discount|coupon|review|best|top \d+|vs\.?)\b/i;
const UGC_DOMAINS = /reddit\.com|quora\.com|forum|community/i;
const VIDEO_DOMAINS = /youtube\.com|vimeo\.com/i;

function classifyByHeuristic(title, domain) {
  const t = title || '';
  const d = domain || '';
  if (UGC_DOMAINS.test(d)) return 'ugc_forum';
  if (VIDEO_DOMAINS.test(d)) return 'video';
  if (COMMERCIAL_HINTS.test(t)) return 'commercial';
  if (INFO_HINTS.test(t)) return 'informational';
  return 'other';
}

const compositionTimeline = (state.timeline || []).map(period => {
  const counts = { informational: 0, commercial: 0, ugc_forum: 0, video: 0, other: 0 };
  for (const r of period.results) {
    const cat = classifyByHeuristic(r.title, r.domain);
    counts[cat] = (counts[cat] || 0) + 1;
  }
  const total = period.results.length || 1;
  const distribution = Object.fromEntries(Object.entries(counts).map(([k, v]) => [k, Math.round((v / total) * 100)]));
  return {
    date: period.date,
    resultCount: period.results.length,
    distribution,
    serpFeatures: period.serpFeatures,
    sampleTitles: period.results.slice(0, 10).map(r => r.title),
    sampleDomains: period.results.slice(0, 10).map(r => r.domain)
  };
});

return [{
  json: {
    ...state,
    compositionTimeline
  }
}];

const state = $input.first().json;
const timeline = state.compositionTimeline || [];

const earliest = timeline[0] || null;
const latest = timeline[timeline.length - 1] || null;

const compositionDelta = {};
if (earliest && latest) {
  const categories = new Set([...Object.keys(earliest.distribution || {}), ...Object.keys(latest.distribution || {})]);
  for (const cat of categories) {
    const before = (earliest.distribution || {})[cat] || 0;
    const after = (latest.distribution || {})[cat] || 0;
    compositionDelta[cat] = after - before;
  }
}

const featureDelta = {};
if (earliest && latest) {
  const featureKeys = new Set([...Object.keys(earliest.serpFeatures || {}), ...Object.keys(latest.serpFeatures || {})]);
  for (const key of featureKeys) {
    featureDelta[key] = { before: !!(earliest.serpFeatures || {})[key], after: !!(latest.serpFeatures || {})[key] };
  }
}

return [{
  json: {
    ...state,
    earliestPeriod: earliest,
    latestPeriod: latest,
    compositionDelta,
    featureDelta
  }
}];

const aiResponse = $input.first().json;
const state = $('Compare Periodic Compositions').first().json;

let parsed;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { periods: [] };
}

const intentTimeline = parsed.periods || [];
const earliestIntent = intentTimeline[0] || null;
const latestIntent = intentTimeline[intentTimeline.length - 1] || null;

return [{
  json: {
    ...state,
    intentTimeline,
    earliestIntent,
    latestIntent
  }
}];

const aiResponse = $input.first().json;
const state = $('Parse Intent Classification Results').first().json;

let drift;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  drift = JSON.parse(cleaned);
} catch (e) {
  drift = { driftDetected: false, fromIntent: '', toIntent: '', confidence: 0, driftNarrative: 'Unable to parse AI response', recommendedActions: [] };
}

const significantDrift = !!drift.driftDetected && (drift.confidence || 0) >= state.driftConfidenceThreshold && state.hasEnoughHistory;

const keywordReport = {
  keyword: state.currentKeyword,
  snapshotTakenAt: state.snapshotTakenAt,
  timelineLength: state.timelineLength,
  hasEnoughHistory: state.hasEnoughHistory,
  compositionDelta: state.compositionDelta,
  featureDelta: state.featureDelta,
  intentTimeline: state.intentTimeline,
  drift,
  significantDrift
};

return [{
  json: {
    ...state,
    drift,
    significantDrift,
    results: [...(state.results || []), keywordReport],
    processedCount: (state.processedCount || 0) + 1
  }
}];

