const item = $input.first().json;
const results = item.results || [];

const keywordsWithDrift = results.filter(r => r.significantDrift).length;

const driftPairs = {};
for (const r of results) {
  if (r.significantDrift && r.drift) {
    const key = (r.drift.fromIntent || '?') + ' \u2192 ' + (r.drift.toIntent || '?');
    driftPairs[key] = (driftPairs[key] || 0) + 1;
  }
}
const topDriftPatterns = Object.entries(driftPairs)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([pattern, count]) => ({ pattern, count }));

return [{
  json: {
    whatsappBusinessPhoneId: item.whatsappBusinessPhoneId,
    whatsappRecipientPhone: item.whatsappRecipientPhone,
    keywordsChecked: results.length,
    keywordsWithDrift,
    topDriftPatterns,
    keywordReports: results
  }
}];
